SELECT tc.table_name, tc.constraint_name, cc.check_clause FROM information_schema.table_constraints tc JOIN information_schema.check_constraints cc ON cc.constraint_schema=tc.constraint_schema AND cc.constraint_name=tc.constraint_name WHERE tc.table_schema='library_db1' AND tc.table_name IN ('subscriptions','payments') AND tc.constraint_type='CHECK' ORDER BY tc.table_name, tc.constraint_name;